class Shape {
public:
    virtual ~Shape() {}
    virtual Shape* clone() const = 0;                    // covariant when overridden
};
class Circle : public Shape {
public:
    Circle* clone() const { return new Circle(*this); }  // C++98 covariant return
};
Shape* raw = shape->clone();  // caller owns it: delete, or adopt into a smart pointer

template <class D>                                 // CRTP clone mixin
class Cloneable : public Shape {
public:
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<D>(static_cast<const D&>(*this));
    }
};
class Circle : public Cloneable<Circle> { /* only the copy ctor is left */ };
